window.CLEANBOT_TEMPLATE_CONTENT={"navItems": [["需求场景", "cleanbot-needs"], ["方案优势", "cleanbot-advantages"], ["核心功能", "cleanbot-features"], ["技术与硬件", "cleanbot-hardware"], ["常见问题", "cleanbot-faq"]], "capabilities": [["空桌识别", "顶部视觉 / 桌号映射"], ["自动派单", "建任务 / 排队 / 到桌"], ["桌面清洁", "到桌复核 / 擦拭 / 验收"], ["现场交互", "触屏确认 / 礼貌离开"]], "needs": [["高校食堂的特殊性", "作为一名学生，我观察到师生用餐后通常会自行将餐具送至回收处，留下的主要是桌面和地面的残留污渍。任务边界相对清楚，适合作为现阶段具身智能的落地起点。", "从餐具已回收的餐桌开始"], ["人离开了，桌子还没恢复可用。", "高峰时段，空桌不一定是干净的桌。清洁人员需要先发现污渍，再赶到处理；发现与排队的等待，也影响下一位同学能否及时落座。", "从确认离席到清洁验收，记录完整用时"], ["派单之后，顾客也可能回来。", "镜头里暂时无人，不代表餐桌已经空闲。书包可能在占座，顾客也可能在机器人到达前返回，系统不能按旧画面直接开始擦拭。", "到桌再确认，把是否清洁的选择交给顾客"]], "advantages": [["周转效率", "从离席到可用，接成一个任务。", "顶部摄像头观察编号餐桌，识别可清洁的脏桌后自动建任务、安排机器人到桌，清洁验收通过后再更新为可用。目标是在约定时限内完成，具体时限待现场测量确定。"], ["人性化交互", "顾客先决定，机器人再行动。", "机器人到桌后重新检查。若有人在场，先停在作业区外，通过触屏询问是否需要清洁；选择离开就取消本次作业，选择清洁也需先让出安全作业空间。"], ["现场可追溯", "慢在哪一步，就改哪一步。", "分别记录识别、排队、行走、交互、擦拭和验收耗时。超时、拒绝、占座与转人工分开记录，用完整任务判断效率，不只展示擦拭动作。"]], "functions": [["识别与编号", "候选方案是在餐厅顶部布置摄像头，将每张桌映射到固定桌号。分别判断人员、遗留物品和脏污；遮挡或判断不明时暂不派单。"], ["生成与调度", "对确认离席、无占座物品且需要清洁的桌面建任务，按等待时间与到期时间安排单台机器人；同一张桌不重复派单，重新占用时撤回旧任务。"], ["到桌与交互", "核对桌号并重新检查现场。有人时先询问；顾客选择暂不清洁则离开，选择清洁且作业区清空后再启动，无人回应不默认同意。"], ["清洁与恢复", "完成擦拭后检查结果，验收通过才标记餐桌可用。先用人工验收建立标准，再验证自动初检；地面清洁另行排期，不阻塞餐桌恢复。"]], "hardware": [["机械臂与清洁端", "负责触达桌面并带动擦拭工具。关注作业范围、接触稳定性与工具更换，具体机构需通过实物验证。"], ["顶部摄像头与近端感知", "顶部摄像头覆盖编号餐桌，负责发现任务；机载 RGB-D、近端视觉等负责到桌复核与作业保护。数量、覆盖、遮挡和标定效果待现场测试，不依赖顶部画面单独判断安全。"], ["移动底盘与地面模块", "底盘承载设备与移动任务；清扫、吸尘、拖地模块按作业需求组合，补给与维护方式仍需验证。"], ["任务服务与机载计算", "任务服务维护桌号、状态、队列与到期时间；机载计算承接到桌复核和执行控制。算力、通信与部署位置按联调结果选型，失联时不继续执行旧任务。"], ["供电与耗材补给", "统筹电池、清洁布、清洁液与污物收集的维护需求。首期由人员检查和补给，续航以实测为准。"], ["触屏与现场保护", "触屏显示目标桌号、清洁询问和离开选项；物理急停与本地接管独立保留。顾客同意不等于可以立即运动，仍需检查人员距离和作业空间。"]], "technology": [["顶部视觉 / 任务服务", "发现与调度", "评估人员、物品与脏污判断，维护桌号映射、去重任务及排队策略；与机器人到桌复核交换状态。", "核心验证方向"], ["Isaac Sim / Isaac Lab", "仿真与数据", "搭建清洁任务环境，结合遥操作示范和任务记录评估接触动作、失败场景与恢复流程。", "仿真与采集方向"], ["NVIDIA GR00T N1.7", "操作策略", "作为候选操作策略，评估清洁任务的输入、动作接口与表现；版本、适配及效果仍需核实。", "候选策略，未定型"], ["ROS 2 / Nav2", "导航与执行", "作为候选技术评估编号餐桌到位、定位、避障与任务取消；自主到桌属于本次闭环的核心验证目标。", "规划与评估中"]], "faqs": [["现在已经能自动清洁餐厅了吗？", "还没有。这是概念与验证阶段的个人产品探索。顶部识别、自动建任务、到桌清洁和现场交互是需要联合验证的目标，不代表已有可部署整机，也尚未量产。"], ["系统怎么知道哪张桌需要清洁？", "初步方案是在餐厅顶部布置摄像头，给餐桌编号并映射机器人地图位置。只有人员已离开、没有占座物品且有待清洁污渍时才生成任务；看不清时等待复核，不把“画面里无人”等同于“可以清洁”。"], ["机器人到了，桌边已经有人怎么办？", "先停止接近，通过触屏询问“抱歉，我来晚了。是否需要帮您清洁桌子？”顾客可选“需要清洁”或“暂不清洁，请离开”。同意后仍需让出安全作业空间；拒绝或无人回应时不启动，离开并更新任务。"], ["需要多久？怎样判断真的提高了效率？", "时限尚未确定，先与场地方约定从确认离席到验收完成的目标。识别、排队、行走、交互、擦拭和验收均计时，超时与转人工也保留。不能用一次擦拭视频代替整轮效率数据。"], ["会收餐具、清洁地面或处理所有污渍吗？", "以师生自行归还餐具为场景前提，遗留餐盘、个人物品、碎片和未知污物转人工处理。先验证餐桌恢复可用，再扩展地面维护；重油污、大面积液体和无人值守运营不在当前范围。"], ["摄像头、硬件参数与现场安全如何确定？", "摄像头数量、安装位置、续航和性能阈值均未冻结。先测覆盖、遮挡与人流，再选型和测试；图像按最小必要范围采集，不需要识别顾客身份。靠近人员、数据失效或异常接触时须停止，并保留独立急停和人工接管。"], ["在哪里了解详细方案和实现进展？", "产品 PRD 列出了状态流转、交互分支、作业边界和验收方法；GitHub 与演示视频展示现阶段探索，不能替代整机及餐厅现场的验证记录。"]]};
